# AWS side of the CI handover for the platform/ingest GitHub Actions workflow.
#
# Two roles, both assumable only via GitHub OIDC from the platform/ingest repository:
#   - plan:  pull requests, read-only on the managed resources
#   - apply: pushes to main, can change the managed resources
#
# Workflow jobs need `permissions: id-token: write` and must pass the matching role ARN to
# aws-actions/configure-aws-credentials.

locals {
  github_repo = "platform/ingest"

  state_bucket     = "ingest-terraform-state"
  state_key        = "ingest/terraform.tfstate"
  state_lock_key   = "${local.state_key}.tflock"
  state_bucket_arn = "arn:aws:s3:::${local.state_bucket}"
}

resource "aws_iam_openid_connect_provider" "github" {
  url            = "https://token.actions.githubusercontent.com"
  client_id_list = ["sts.amazonaws.com"]
}

data "aws_iam_policy_document" "plan_trust" {
  statement {
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = ["sts.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:sub"
      values   = ["repo:${local.github_repo}:pull_request"]
    }
  }
}

data "aws_iam_policy_document" "apply_trust" {
  statement {
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [aws_iam_openid_connect_provider.github.arn]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:aud"
      values   = ["sts.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "token.actions.githubusercontent.com:sub"
      values   = ["repo:${local.github_repo}:ref:refs/heads/main"]
    }
  }
}

resource "aws_iam_role" "plan" {
  name                 = "ingest-terraform-plan"
  assume_role_policy   = data.aws_iam_policy_document.plan_trust.json
  max_session_duration = 3600
}

resource "aws_iam_role" "apply" {
  name                 = "ingest-terraform-apply"
  assume_role_policy   = data.aws_iam_policy_document.apply_trust.json
  max_session_duration = 3600
}

# Remote state access. The s3 backend uses a lockfile, so even plan needs to write the lock object.
data "aws_iam_policy_document" "state_read" {
  statement {
    sid       = "ListStateBucket"
    actions   = ["s3:ListBucket"]
    resources = [local.state_bucket_arn]
  }

  statement {
    sid       = "ReadState"
    actions   = ["s3:GetObject"]
    resources = ["${local.state_bucket_arn}/${local.state_key}"]
  }

  statement {
    sid       = "Lock"
    actions   = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject"]
    resources = ["${local.state_bucket_arn}/${local.state_lock_key}"]
  }
}

data "aws_iam_policy_document" "state_write" {
  source_policy_documents = [data.aws_iam_policy_document.state_read.json]

  statement {
    sid       = "WriteState"
    actions   = ["s3:PutObject"]
    resources = ["${local.state_bucket_arn}/${local.state_key}"]
  }
}

# Read-only access to the resources this configuration manages (needed for refresh during plan).
data "aws_iam_policy_document" "resources_read" {
  statement {
    sid       = "ReadBucket"
    actions   = ["s3:GetBucket*", "s3:GetAccelerateConfiguration", "s3:GetEncryptionConfiguration", "s3:GetLifecycleConfiguration", "s3:GetReplicationConfiguration", "s3:GetObjectLockConfiguration", "s3:ListBucket"]
    resources = [aws_s3_bucket.landing.arn]
  }

  statement {
    sid       = "ReadQueue"
    actions   = ["sqs:GetQueueAttributes", "sqs:GetQueueUrl", "sqs:ListQueueTags"]
    resources = [aws_sqs_queue.events.arn]
  }

  statement {
    sid = "ReadTable"
    actions = [
      "dynamodb:DescribeTable",
      "dynamodb:DescribeContinuousBackups",
      "dynamodb:DescribeTimeToLive",
      "dynamodb:ListTagsOfResource",
    ]
    resources = [aws_dynamodb_table.checkpoints.arn]
  }
}

# Write access, limited to the resources above. No IAM, no access to other resources, no object data access.
data "aws_iam_policy_document" "resources_write" {
  source_policy_documents = [data.aws_iam_policy_document.resources_read.json]

  statement {
    sid = "ManageBucket"
    actions = [
      "s3:CreateBucket",
      "s3:DeleteBucket",
      "s3:PutBucket*",
      "s3:PutAccelerateConfiguration",
      "s3:PutEncryptionConfiguration",
      "s3:PutLifecycleConfiguration",
      "s3:PutReplicationConfiguration",
    ]
    resources = [aws_s3_bucket.landing.arn]
  }

  statement {
    sid = "ManageQueue"
    actions = [
      "sqs:CreateQueue",
      "sqs:DeleteQueue",
      "sqs:SetQueueAttributes",
      "sqs:TagQueue",
      "sqs:UntagQueue",
    ]
    resources = [aws_sqs_queue.events.arn]
  }

  statement {
    sid = "ManageTable"
    actions = [
      "dynamodb:CreateTable",
      "dynamodb:DeleteTable",
      "dynamodb:UpdateTable",
      "dynamodb:UpdateContinuousBackups",
      "dynamodb:UpdateTimeToLive",
      "dynamodb:TagResource",
      "dynamodb:UntagResource",
    ]
    resources = [aws_dynamodb_table.checkpoints.arn]
  }
}

resource "aws_iam_role_policy" "plan_state" {
  name   = "terraform-state"
  role   = aws_iam_role.plan.id
  policy = data.aws_iam_policy_document.state_read.json
}

resource "aws_iam_role_policy" "plan_resources" {
  name   = "managed-resources-read"
  role   = aws_iam_role.plan.id
  policy = data.aws_iam_policy_document.resources_read.json
}

resource "aws_iam_role_policy" "apply_state" {
  name   = "terraform-state"
  role   = aws_iam_role.apply.id
  policy = data.aws_iam_policy_document.state_write.json
}

resource "aws_iam_role_policy" "apply_resources" {
  name   = "managed-resources-write"
  role   = aws_iam_role.apply.id
  policy = data.aws_iam_policy_document.resources_write.json
}

output "ci_plan_role_arn" {
  description = "Role for the pull_request plan job."
  value       = aws_iam_role.plan.arn
}

output "ci_apply_role_arn" {
  description = "Role for the main-branch apply job."
  value       = aws_iam_role.apply.arn
}
EOF
terraform fmt -check 2>&1 | head; terraform init -backend=false >/dev/null 2>&1 && terraform validate 2>&1 | tail -5

